CREATE TABLE IF NOT EXISTS sd_funding(ticket_id TEXT PRIMARY KEY REFERENCES service_tickets(id),mode TEXT NOT NULL CHECK(mode IN ('sla','billable','internal')),contract_id TEXT REFERENCES managed_contracts(id),sla_entry_id TEXT REFERENCES contract_entries(id),status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sd_estimates(ticket_id TEXT NOT NULL REFERENCES service_tickets(id),version INTEGER NOT NULL,data TEXT NOT NULL,proposed_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'awaiting_customer',decided_by TEXT REFERENCES users(id),decision_note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT,PRIMARY KEY(ticket_id,version));
CREATE TABLE IF NOT EXISTS customer_service_authority(user_id TEXT NOT NULL REFERENCES users(id),customer_id TEXT NOT NULL REFERENCES customers(id),can_authorize_billable INTEGER NOT NULL DEFAULT 0 CHECK(can_authorize_billable IN (0,1)),updated_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,customer_id));
CREATE TABLE IF NOT EXISTS sd_public_comments(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES service_tickets(id),author_id TEXT NOT NULL REFERENCES users(id),author_type TEXT NOT NULL CHECK(author_type IN ('customer','support')),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sd_customer_requests(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES service_tickets(id),requested_by TEXT NOT NULL REFERENCES users(id),request_type TEXT NOT NULL CHECK(request_type IN ('escalation','reopen','cancellation')),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',decision_note TEXT,decided_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS sd_customer_pending_request ON sd_customer_requests(ticket_id,request_type) WHERE status IN ('pending','acknowledged');
CREATE TABLE IF NOT EXISTS sd_customer_knowledge(customer_id TEXT NOT NULL REFERENCES customers(id),article_id TEXT NOT NULL REFERENCES kb_articles(id),version INTEGER NOT NULL,shared_by TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,shared_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(customer_id,article_id),FOREIGN KEY(article_id,version) REFERENCES kb_versions(article_id,version));
CREATE INDEX IF NOT EXISTS sd_public_comments_ticket ON sd_public_comments(ticket_id,created_at);
CREATE TRIGGER IF NOT EXISTS sd_estimate_snapshot_guard BEFORE UPDATE OF data ON sd_estimates BEGIN SELECT RAISE(ABORT,'Billable estimate version is immutable'); END;
CREATE TRIGGER IF NOT EXISTS sd_billable_execution_guard BEFORE UPDATE OF status ON service_tickets WHEN NEW.status IN ('in_progress','resolved','closed') AND EXISTS(SELECT 1 FROM sd_funding f WHERE f.ticket_id=NEW.id AND f.mode='billable' AND f.status<>'approved' AND NOT(f.status='cancelled_no_work' AND NEW.status IN ('resolved','closed') AND EXISTS(SELECT 1 FROM sd_profiles s WHERE s.ticket_id=NEW.id AND json_extract(s.data,'$.resolution_code')='cancelled'))) BEGIN SELECT RAISE(ABORT,'Approved billable estimate required'); END;
CREATE TABLE IF NOT EXISTS sd_work_logs(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES service_tickets(id),user_id TEXT NOT NULL REFERENCES users(id),work_date TEXT NOT NULL,hours_units INTEGER NOT NULL CHECK(hours_units>0 AND hours_units<=2400),funding_mode TEXT NOT NULL,funding_version INTEGER NOT NULL DEFAULT 0,contract_id TEXT REFERENCES managed_contracts(id),sla_entry_id TEXT REFERENCES contract_entries(id),notes TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted',decided_by TEXT REFERENCES users(id),decision_note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT);
CREATE TRIGGER IF NOT EXISTS sd_daily_hours BEFORE INSERT ON sd_work_logs WHEN NEW.status='submitted' AND NEW.hours_units+COALESCE((SELECT SUM(hours_units) FROM sd_work_logs WHERE user_id=NEW.user_id AND work_date=NEW.work_date AND status IN ('submitted','approved')),0)+COALESCE((SELECT SUM(hours_units) FROM pm_time_entries WHERE user_id=NEW.user_id AND work_date=NEW.work_date AND status IN ('submitted','approved')),0)>2400 BEGIN SELECT RAISE(ABORT,'Combined daily hours exceeded'); END;
DROP TRIGGER IF EXISTS pm_daily_hours;
CREATE TRIGGER pm_daily_hours BEFORE INSERT ON pm_time_entries WHEN NEW.status='submitted' AND NEW.hours_units+COALESCE((SELECT SUM(hours_units) FROM pm_time_entries WHERE user_id=NEW.user_id AND work_date=NEW.work_date AND status IN ('submitted','approved')),0)+COALESCE((SELECT SUM(hours_units) FROM sd_work_logs WHERE user_id=NEW.user_id AND work_date=NEW.work_date AND status IN ('submitted','approved')),0)>2400 BEGIN SELECT RAISE(ABORT,'PM daily hours exceeded'); END;
CREATE TRIGGER IF NOT EXISTS sd_sla_hours BEFORE INSERT ON sla_time_entries WHEN NEW.id LIKE 'sd-%' AND NEW.status='recorded' AND (COALESCE((SELECT CAST(ROUND(CAST(json_extract(data,'$.hours_sold') AS REAL)*100) AS INTEGER) FROM contract_entries WHERE id=NEW.sla_entry_id),0)<NEW.hours_units+COALESCE((SELECT SUM(hours_units) FROM sla_time_entries WHERE sla_entry_id=NEW.sla_entry_id AND status='recorded'),0)) BEGIN SELECT RAISE(ABORT,'Insufficient SLA hours'); END;
